s32 retargetMatchingVoices(s32, s32, s32);                   /* extern */
s32 voiceLookupSlot(s32, s32);                        /* extern */

/* Retargets matching voices if the slot is in use; returns -1 when the slot is invalid, unused or nothing matched. */ s32 retargetVoicesIfSlotUsed(s32 newTarget, s32 slotRow, s32 slotCol) {
    s32 row;
    s32 col;
    s32 result;

    row = slotRow & 0xFF;
    if ((row == 0xFF) || (col = slotCol & 0xFF, ((voiceLookupSlot(row, col) & 0xFF) == 0)) || (result = retargetMatchingVoices(newTarget & 0x7F, row, col), (result == -1))) {
        return -1;
    }
    return result;
}
